package io.invenlio.sales;
import io.invenlio.catalog.CatalogInventoryLookup;import io.invenlio.inventory.InventoryReservationAllocation;import io.invenlio.organization.*;import io.invenlio.warehouse.WarehouseAvailability;import java.math.*;import java.time.*;import java.util.*;import org.springframework.context.ApplicationEventPublisher;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service class SalesOrderService{private final AuthorizationService auth;private final AuditTrail audit;private final JdbcTemplate db;private final CatalogInventoryLookup catalog;private final WarehouseAvailability warehouses;private final InventoryReservationAllocation inventory;private final ApplicationEventPublisher events;SalesOrderService(AuthorizationService a,AuditTrail t,JdbcTemplate d,CatalogInventoryLookup c,WarehouseAvailability w,InventoryReservationAllocation i,ApplicationEventPublisher e){auth=a;audit=t;db=d;catalog=c;warehouses=w;inventory=i;events=e;}
 @Transactional OrderView create(Create c){var a=auth.require(Permission.SALES_ORDER_MANAGE);Customer x=customer(a.tenantId(),c.customerId);var w=warehouses.findActiveWarehouse(a.tenantId(),c.warehouseId).orElseThrow(()->err("WAREHOUSE_NOT_AVAILABLE","Active fulfillment warehouse required"));String cur=currency(c.currency==null?x.currency:c.currency);UUID id=UUID.randomUUID();String n=number(a.tenantId());String ship=blank(c.shippingAddress)==null?x.shippingAddress:c.shippingAddress.trim();String bill=blank(c.billingAddress)==null?x.billingAddress:c.billingAddress.trim();db.update("INSERT INTO sales_orders(id,tenant_id,customer_id,fulfillment_warehouse_id,sales_order_number,status,currency,customer_reference,requested_delivery_date,shipping_address_snapshot,billing_address_snapshot,customer_number_snapshot,customer_name_snapshot,warehouse_code_snapshot,warehouse_name_snapshot,subtotal,created_by,created_at,updated_at,version)VALUES(?,?,?,?,?,'DRAFT',?,?,?,?,?,?,?,?,?,0,?,now(),now(),0)",id,a.tenantId(),x.id,w.warehouseId(),n,cur,blank(c.customerReference),c.requestedDeliveryDate,ship,bill,x.number,x.name,w.code(),w.name(),a.userId());audit.record(a,"SALES_ORDER_CREATED","sales-order",id.toString());events.publishEvent(new SalesEvents.SalesOrderCreated(a.tenantId(),id));return get0(a.tenantId(),id);}
 @Transactional(readOnly=true)OrderView get(UUID id){var a=auth.require(Permission.SALES_ORDER_READ);return get0(a.tenantId(),id);}
 @Transactional(readOnly=true)List<OrderView>list(String number,UUID customerId,UUID warehouseId,String status,LocalDate createdFrom,LocalDate createdTo,LocalDate requestedFrom,LocalDate requestedTo,String q,int page,int size,String sort){var a=auth.require(Permission.SALES_ORDER_READ);page(page,size);String order=switch(sort==null?"createdAt":sort){case"orderNumber"->"sales_order_number";case"status"->"status";case"createdAt"->"created_at DESC";case"updatedAt"->"updated_at DESC";case"requestedDeliveryDate"->"requested_delivery_date NULLS LAST";case"subtotal"->"subtotal DESC";default->throw err("INVALID_SORT","Unsupported sort");};String like=q==null?null:"%"+q.trim().toLowerCase()+"%";return db.query("SELECT id FROM sales_orders WHERE tenant_id=? AND(?::text IS NULL OR sales_order_number=?::text)AND(?::uuid IS NULL OR customer_id=?::uuid)AND(?::uuid IS NULL OR fulfillment_warehouse_id=?::uuid)AND(?::text IS NULL OR status=?::text)AND(?::date IS NULL OR created_at>=?::date)AND(?::date IS NULL OR created_at<?::date+1)AND(?::date IS NULL OR requested_delivery_date>=?::date)AND(?::date IS NULL OR requested_delivery_date<=?::date)AND(?::text IS NULL OR lower(sales_order_number||' '||customer_name_snapshot||' '||coalesce(customer_reference,''))LIKE?::text)ORDER BY "+order+",id OFFSET ? LIMIT ?",(r,n)->get0(a.tenantId(),(UUID)r.getObject(1)),a.tenantId(),number,number,customerId,customerId,warehouseId,warehouseId,status,status,createdFrom,createdFrom,createdTo,createdTo,requestedFrom,requestedFrom,requestedTo,requestedTo,like,like,page*size,size);}
 @Transactional OrderView update(UUID id,Update c,long version){var a=auth.require(Permission.SALES_ORDER_MANAGE);OrderView o=get0(a.tenantId(),id);if(!o.status.equals("DRAFT"))throw err("SALES_ORDER_NOT_EDITABLE","Only draft orders are editable");var w=warehouses.findActiveWarehouse(a.tenantId(),c.warehouseId).orElseThrow(()->err("WAREHOUSE_NOT_AVAILABLE","Active fulfillment warehouse required"));if(db.update("UPDATE sales_orders SET fulfillment_warehouse_id=?,warehouse_code_snapshot=?,warehouse_name_snapshot=?,customer_reference=?,requested_delivery_date=?,shipping_address_snapshot=?,billing_address_snapshot=?,updated_at=now(),version=version+1 WHERE tenant_id=? AND id=? AND status='DRAFT' AND version=?",w.warehouseId(),w.code(),w.name(),blank(c.customerReference),c.requestedDeliveryDate,required(c.shippingAddress,"Shipping address required"),blank(c.billingAddress),a.tenantId(),id,version)!=1)throw err("CONCURRENT_MODIFICATION","Sales order changed");audit.record(a,"SALES_ORDER_UPDATED","sales-order",id.toString());return get0(a.tenantId(),id);}
 @Transactional LineView addLine(UUID orderId,LineCommand c){var a=auth.require(Permission.SALES_ORDER_MANAGE);OrderView o=lock(a.tenantId(),orderId);if(!o.status.equals("DRAFT"))throw err("SALES_ORDER_NOT_EDITABLE","Only draft orders are editable");var v=variant(a.tenantId(),c.variantId);BigDecimal q=quantity(c.quantity,v.discrete()),price=money(c.unitPrice);int line=db.queryForObject("SELECT COALESCE(max(line_number),0)+1 FROM sales_order_lines WHERE tenant_id=? AND sales_order_id=?",Integer.class,a.tenantId(),orderId);UUID id=UUID.randomUUID();db.update("INSERT INTO sales_order_lines(id,tenant_id,sales_order_id,line_number,variant_id,sku_snapshot,description_snapshot,ordered_quantity,unit_code,unit_price,currency,line_subtotal,created_at,updated_at,version)VALUES(?,?,?,?,?,?,?,?,?,?,?,?,now(),now(),0)",id,a.tenantId(),orderId,line,v.variantId(),v.sku(),v.displayName(),q,v.baseUnit(),price,o.currency,q.multiply(price));total(a.tenantId(),orderId);touch(a.tenantId(),orderId,o.version);audit.record(a,"SALES_ORDER_UPDATED","sales-order",orderId.toString());return line(a.tenantId(),orderId,id);}
 @Transactional LineView updateLine(UUID orderId,UUID lineId,LineCommand c,long version){var a=auth.require(Permission.SALES_ORDER_MANAGE);OrderView o=lock(a.tenantId(),orderId);if(!o.status.equals("DRAFT"))throw err("SALES_ORDER_NOT_EDITABLE","Only draft orders are editable");LineView old=line(a.tenantId(),orderId,lineId);var v=variant(a.tenantId(),old.variantId);BigDecimal q=quantity(c.quantity,v.discrete()),price=money(c.unitPrice);if(db.update("UPDATE sales_order_lines SET ordered_quantity=?,unit_price=?,line_subtotal=?,updated_at=now(),version=version+1 WHERE tenant_id=? AND sales_order_id=? AND id=? AND version=?",q,price,q.multiply(price),a.tenantId(),orderId,lineId,version)!=1)throw err("CONCURRENT_MODIFICATION","Sales order line changed");total(a.tenantId(),orderId);touch(a.tenantId(),orderId,o.version);audit.record(a,"SALES_ORDER_UPDATED","sales-order",orderId.toString());return line(a.tenantId(),orderId,lineId);}
 @Transactional void removeLine(UUID orderId,UUID lineId,long version){var a=auth.require(Permission.SALES_ORDER_MANAGE);OrderView o=lock(a.tenantId(),orderId);if(!o.status.equals("DRAFT"))throw err("SALES_ORDER_NOT_EDITABLE","Only draft orders are editable");if(db.update("DELETE FROM sales_order_lines WHERE tenant_id=? AND sales_order_id=? AND id=? AND version=?",a.tenantId(),orderId,lineId,version)!=1)throw err("CONCURRENT_MODIFICATION","Sales order line changed");total(a.tenantId(),orderId);touch(a.tenantId(),orderId,o.version);audit.record(a,"SALES_ORDER_UPDATED","sales-order",orderId.toString());}
 @Transactional OrderView confirm(UUID id,long version){var a=auth.require(Permission.SALES_ORDER_MANAGE);OrderView o=lock(a.tenantId(),id);if(!o.status.equals("DRAFT")||o.lines.isEmpty())throw err("SALES_ORDER_NOT_CONFIRMABLE","A non-empty draft is required");if(!customer(a.tenantId(),o.customerId).status.equals("ACTIVE"))throw err("CUSTOMER_NOT_ACTIVE","Customer must be active");warehouses.findActiveWarehouse(a.tenantId(),o.warehouseId).orElseThrow(()->err("WAREHOUSE_NOT_AVAILABLE","Warehouse must be active"));for(var l:o.lines)variant(a.tenantId(),l.variantId);if(db.update("UPDATE sales_orders SET status='CONFIRMED',updated_at=now(),version=version+1 WHERE tenant_id=? AND id=? AND status='DRAFT' AND version=?",a.tenantId(),id,version)!=1)throw err("CONCURRENT_MODIFICATION","Sales order changed");audit.record(a,"SALES_ORDER_CONFIRMED","sales-order",id.toString());events.publishEvent(new SalesEvents.SalesOrderConfirmed(a.tenantId(),id));return get0(a.tenantId(),id);}
 @Transactional OrderView allocate(UUID id){var a=auth.require(Permission.SALES_ORDER_ALLOCATE);OrderView o=lock(a.tenantId(),id);if(!"NOT_STARTED".equals(o.fulfillmentStatus))throw err("SALES_ORDER_FULFILLMENT_STARTED","Sales order fulfillment has started");if(!Set.of("CONFIRMED","PARTIALLY_ALLOCATED").contains(o.status))throw err("SALES_ORDER_NOT_ALLOCATABLE","Confirmed or partially allocated order required");reconcile(a.tenantId(),o);for(LineView l:o.lines){BigDecimal remaining=l.orderedQuantity.subtract(l.allocatedQuantity);if(remaining.signum()<=0)continue;for(var c:inventory.candidates(a.tenantId(),l.variantId,o.warehouseId,1000)){if(remaining.signum()<=0)break;BigDecimal take=c.serialId()==null?remaining.min(c.available()):BigDecimal.ONE.min(remaining);if(take.signum()<=0)continue;String key="sales:"+UUID.randomUUID();var reserved=inventory.reserve(a.tenantId(),a.userId(),key,l.id.toString(),l.variantId,o.warehouseId,c.locationId(),c.lotId(),c.serialId(),take);if(reserved.isEmpty())continue;var r=reserved.get();db.update("INSERT INTO sales_allocations(id,tenant_id,sales_order_id,sales_order_line_id,inventory_reservation_id,allocated_quantity,status,created_at)VALUES(?,?,?,?,?,?,'ACTIVE',now())",UUID.randomUUID(),a.tenantId(),id,l.id,r.id(),take);db.update("UPDATE sales_order_lines SET allocated_quantity=allocated_quantity+?,updated_at=now(),version=version+1 WHERE tenant_id=? AND sales_order_id=? AND id=? AND allocated_quantity+?<=ordered_quantity",take,a.tenantId(),id,l.id,take);remaining=remaining.subtract(take);}}OrderView result=get0(a.tenantId(),id);boolean full=result.lines.stream().allMatch(x->x.backorderedQuantity().signum()==0);String status=full?"ALLOCATED":"PARTIALLY_ALLOCATED";db.update("UPDATE sales_orders SET status=?,updated_at=now(),version=version+1 WHERE tenant_id=? AND id=?",status,a.tenantId(),id);audit.record(a,full?"SALES_ORDER_ALLOCATED":"SALES_ORDER_PARTIALLY_ALLOCATED","sales-order",id.toString());events.publishEvent(new SalesEvents.SalesOrderAllocated(a.tenantId(),id,!full));OrderView done=get0(a.tenantId(),id);reconcile(a.tenantId(),done);return done;}
 @Transactional OrderView cancel(UUID id,long version,String reason){var a=auth.require(Permission.SALES_ORDER_MANAGE);OrderView o=lock(a.tenantId(),id);String fulfillment=db.queryForObject("SELECT fulfillment_status FROM sales_orders WHERE tenant_id=? AND id=?",String.class,a.tenantId(),id);if(!"NOT_STARTED".equals(fulfillment))throw err("SALES_ORDER_FULFILLMENT_STARTED","Sales order fulfillment has started");if(o.status.equals("CANCELLED"))return o;if(!Set.of("DRAFT","CONFIRMED","PARTIALLY_ALLOCATED","ALLOCATED").contains(o.status))throw err("SALES_ORDER_NOT_CANCELLABLE","Order cannot be cancelled");reconcile(a.tenantId(),o);List<UUID>rs=db.query("SELECT inventory_reservation_id FROM sales_allocations WHERE tenant_id=? AND sales_order_id=? AND status='ACTIVE' ORDER BY id",(r,n)->(UUID)r.getObject(1),a.tenantId(),id);for(UUID r:rs)inventory.release(a.tenantId(),a.userId(),r);db.update("UPDATE sales_allocations SET status='RELEASED' WHERE tenant_id=? AND sales_order_id=? AND status='ACTIVE'",a.tenantId(),id);if(db.update("UPDATE sales_orders SET status='CANCELLED',cancelled_at=now(),cancelled_by=?,cancellation_reason=?,updated_at=now(),version=version+1 WHERE tenant_id=? AND id=? AND version=?",a.userId(),required(reason,"Cancellation reason required"),a.tenantId(),id,version)!=1)throw err("CONCURRENT_MODIFICATION","Sales order changed");db.update("UPDATE sales_order_lines SET allocated_quantity=0,updated_at=now(),version=version+1 WHERE tenant_id=? AND sales_order_id=?",a.tenantId(),id);audit.record(a,"SALES_ORDER_CANCELLED","sales-order",id.toString());events.publishEvent(new SalesEvents.SalesOrderCancelled(a.tenantId(),id));return get0(a.tenantId(),id);}
 private void reconcile(UUID t,OrderView o){for(var l:o.lines){BigDecimal active=BigDecimal.ZERO;var ids=db.query("SELECT inventory_reservation_id FROM sales_allocations WHERE tenant_id=? AND sales_order_line_id=? AND status='ACTIVE'",(r,n)->(UUID)r.getObject(1),t,l.id);for(UUID id:ids)active=active.add(inventory.activeQuantity(t,id,l.id.toString()));if(active.compareTo(l.allocatedQuantity)!=0)throw err("ALLOCATION_RECONCILIATION_FAILED","Sales allocation does not match active inventory reservations");}}
 private OrderView lock(UUID t,UUID id){var rows=db.query("SELECT id FROM sales_orders WHERE tenant_id=? AND id=? FOR UPDATE",(r,n)->(UUID)r.getObject(1),t,id);if(rows.isEmpty())throw err("SALES_ORDER_NOT_FOUND","Sales order not found");return get0(t,id);}private void total(UUID t,UUID id){db.update("UPDATE sales_orders SET subtotal=(SELECT COALESCE(sum(line_subtotal),0)FROM sales_order_lines WHERE tenant_id=? AND sales_order_id=?)WHERE tenant_id=? AND id=?",t,id,t,id);}private void touch(UUID t,UUID id,long v){if(db.update("UPDATE sales_orders SET updated_at=now(),version=version+1 WHERE tenant_id=? AND id=? AND version=?",t,id,v)!=1)throw err("CONCURRENT_MODIFICATION","Sales order changed");}
 private OrderView get0(UUID t,UUID id){var x=db.query("SELECT id,sales_order_number,customer_id,fulfillment_warehouse_id,status,currency,customer_reference,requested_delivery_date,shipping_address_snapshot,billing_address_snapshot,customer_number_snapshot,customer_name_snapshot,warehouse_code_snapshot,warehouse_name_snapshot,subtotal,created_at,updated_at,version,cancelled_at,cancellation_reason,fulfillment_status FROM sales_orders WHERE tenant_id=? AND id=?",(r,n)->new OrderView((UUID)r.getObject(1),r.getString(2),(UUID)r.getObject(3),(UUID)r.getObject(4),r.getString(5),r.getString(6),r.getString(7),r.getObject(8,LocalDate.class),r.getString(9),r.getString(10),r.getString(11),r.getString(12),r.getString(13),r.getString(14),r.getBigDecimal(15),r.getTimestamp(16).toInstant(),r.getTimestamp(17).toInstant(),r.getLong(18),r.getTimestamp(19)==null?null:r.getTimestamp(19).toInstant(),r.getString(20),r.getString(21),lines(t,id)),t,id);if(x.isEmpty())throw err("SALES_ORDER_NOT_FOUND","Sales order not found");return x.getFirst();}private List<LineView>lines(UUID t,UUID id){return db.query("SELECT id,line_number,variant_id,sku_snapshot,description_snapshot,ordered_quantity,unit_code,unit_price,currency,line_subtotal,allocated_quantity,created_at,updated_at,version,picked_quantity,packed_quantity FROM sales_order_lines WHERE tenant_id=? AND sales_order_id=? ORDER BY line_number,id",(r,n)->new LineView((UUID)r.getObject(1),r.getInt(2),(UUID)r.getObject(3),r.getString(4),r.getString(5),r.getBigDecimal(6),r.getString(7),r.getBigDecimal(8),r.getString(9),r.getBigDecimal(10),r.getBigDecimal(11),r.getTimestamp(12).toInstant(),r.getTimestamp(13).toInstant(),r.getLong(14),r.getBigDecimal(15),r.getBigDecimal(16)),t,id);}private LineView line(UUID t,UUID o,UUID id){return lines(t,o).stream().filter(x->x.id.equals(id)).findFirst().orElseThrow(()->err("SALES_ORDER_LINE_NOT_FOUND","Line not found"));}
 private Customer customer(UUID t,UUID id){var x=db.query("SELECT id,customer_number,name,status,default_currency,shipping_address,billing_address FROM customers WHERE tenant_id=? AND id=?",(r,n)->new Customer((UUID)r.getObject(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7)),t,id);if(x.isEmpty())throw err("CUSTOMER_NOT_FOUND","Customer not found");return x.getFirst();}private CatalogInventoryLookup.InventoryVariant variant(UUID t,UUID id){var v=catalog.findInventoryVariant(t,id).orElseThrow(()->err("VARIANT_NOT_FOUND","Variant not found"));if(!v.status().equals("ACTIVE"))throw err("VARIANT_NOT_ELIGIBLE","Variant must be active");return v;}private String number(UUID t){int y=Year.now(ZoneOffset.UTC).getValue();long n=db.queryForObject("INSERT INTO sales_order_number_counters(tenant_id,order_year,next_value)VALUES(?,?,2)ON CONFLICT(tenant_id,order_year)DO UPDATE SET next_value=sales_order_number_counters.next_value+1 RETURNING next_value-1",Long.class,t,y);return "SO-"+y+"-"+String.format(Locale.ROOT,"%06d",n);}private static BigDecimal quantity(String s,boolean discrete){try{BigDecimal q=new BigDecimal(s).stripTrailingZeros();if(q.signum()<=0||q.scale()>6||q.precision()>19||(discrete&&q.scale()>0))throw new Exception();return q.setScale(6);}catch(Exception e){throw err("INVALID_ORDER_QUANTITY","Positive base-UOM quantity required");}}private static BigDecimal money(String s){try{BigDecimal q=new BigDecimal(s).stripTrailingZeros();if(q.signum()<0||q.scale()>6||q.precision()>19)throw new Exception();return q.setScale(6);}catch(Exception e){throw err("INVALID_UNIT_PRICE","Non-negative NUMERIC(19,6) price required");}}private static String currency(String c){try{return Currency.getInstance(c.trim().toUpperCase()).getCurrencyCode();}catch(Exception e){throw err("INVALID_CURRENCY","ISO 4217 currency required");}}private static String blank(String s){return s==null||s.isBlank()?null:s.trim();}private static String required(String s,String m){if(s==null||s.isBlank())throw err("INVALID_SALES_ORDER",m);return s.trim();}private static void page(int p,int s){if(p<0||s<1||s>100)throw err("INVALID_PAGINATION","Invalid pagination");}private static SalesException err(String c,String m){return new SalesException(c,m);}
 record Create(UUID customerId,UUID warehouseId,String currency,String customerReference,LocalDate requestedDeliveryDate,String shippingAddress,String billingAddress){}record Update(UUID warehouseId,String customerReference,LocalDate requestedDeliveryDate,String shippingAddress,String billingAddress){}record LineCommand(UUID variantId,String quantity,String unitPrice){}record Customer(UUID id,String number,String name,String status,String currency,String shippingAddress,String billingAddress){}record OrderView(UUID id,String orderNumber,UUID customerId,UUID warehouseId,String status,String currency,String customerReference,LocalDate requestedDeliveryDate,String shippingAddress,String billingAddress,String customerNumber,String customerName,String warehouseCode,String warehouseName,BigDecimal subtotal,Instant createdAt,Instant updatedAt,long version,Instant cancelledAt,String cancellationReason,String fulfillmentStatus,List<LineView>lines){public BigDecimal getTotalOrdered(){return lines.stream().map(LineView::orderedQuantity).reduce(BigDecimal.ZERO,BigDecimal::add);}public BigDecimal getTotalAllocated(){return lines.stream().map(LineView::allocatedQuantity).reduce(BigDecimal.ZERO,BigDecimal::add);}}record LineView(UUID id,int lineNumber,UUID variantId,String sku,String description,BigDecimal orderedQuantity,String unitCode,BigDecimal unitPrice,String currency,BigDecimal subtotal,BigDecimal allocatedQuantity,Instant createdAt,Instant updatedAt,long version,BigDecimal pickedQuantity,BigDecimal packedQuantity){BigDecimal backorderedQuantity(){return orderedQuantity.subtract(allocatedQuantity);}public BigDecimal getBackorderedQuantity(){return backorderedQuantity();}}
}
